// ============================================================
// NODE: Normalize Email Data
// Identical to Milestone 1 — extracts clean fields from
// the raw Gmail payload.
// ============================================================

const item = $input.item.json;

const fromRaw = item.from || '';
let senderEmail = '';
let senderName = '';

const emailMatch = fromRaw.match(/<([^>]+)>/);
if (emailMatch) {
  senderEmail = emailMatch[1].trim().toLowerCase();
  senderName = fromRaw.split('<')[0].trim().replace(/"/g, '');
} else {
  senderEmail = fromRaw.trim().toLowerCase();
  senderName = fromRaw.split('@')[0].trim();
}

const firstName = senderName.split(' ')[0] || 'there';
const bodyText = item.text || item.snippet || '';
const bodyClean = bodyText.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim().substring(0, 3000);
const fullTextLower = `${item.subject || ''} ${bodyClean}`.toLowerCase();

// Detect if this is a REPLY to our earlier proposal
// Gmail threads: if subject starts with 'Re:' and body contains confirmation language
const isReply = (item.subject || '').toLowerCase().startsWith('re:');
const hasThreadId = !!item.threadId;

return {
  json: {
    messageId:     item.id || '',
    threadId:      item.threadId || '',
    senderEmail,
    senderName,
    firstName,
    subject:       item.subject || '(No Subject)',
    body:          bodyClean,
    fullTextLower,
    receivedAt:    item.date || new Date().toISOString(),
    isReply,
    hasThreadId,
    _raw:          item
  }
};

// ============================================================
// NODE: Safety Filter
// IDENTICAL to Milestone 1 — never skip this.
// Runs before any AI or booking logic.
// ============================================================

const text = $input.item.json.fullTextLower || '';

const legalPatterns = ['complaint','complain','solicitor','legal action','lawsuit','sue','court','ombudsman','data breach','gdpr breach','negligence','malpractice','report you'];
const safeguardingPatterns = ['safeguarding','safeguard','at risk','risk of harm','abuse','neglect','domestic violence','threatened','violence','police','social services'];
const crisisPatterns = ['suicid','self harm','self-harm','overdose','want to die','end my life','hurt myself','crisis','emergency','not safe'];

const matchedLegal        = legalPatterns.filter(p => text.includes(p));
const matchedSafeguarding = safeguardingPatterns.filter(p => text.includes(p));
const matchedCrisis       = crisisPatterns.filter(p => text.includes(p));

const isFlagged = matchedLegal.length > 0 || matchedSafeguarding.length > 0 || matchedCrisis.length > 0;

let flagReason = '';
let flagCategory = '';

if (matchedCrisis.length > 0) {
  flagCategory = 'CRISIS_RISK';
  flagReason = `Crisis language: ${matchedCrisis.join(', ')}`;
} else if (matchedSafeguarding.length > 0) {
  flagCategory = 'SAFEGUARDING';
  flagReason = `Safeguarding language: ${matchedSafeguarding.join(', ')}`;
} else if (matchedLegal.length > 0) {
  flagCategory = 'LEGAL_COMPLAINT';
  flagReason = `Legal language: ${matchedLegal.join(', ')}`;
}

return {
  json: {
    ...$input.item.json,
    safety: { isFlagged, flagCategory, flagReason }
  }
};

// ============================================================
// NODE: Parse AI Intent Response
// Bulletproof parser — every failure → manual_review
// ============================================================

const upstream = $input.item.json;
let aiText = '';

try {
  aiText = upstream.text || upstream.message?.content || upstream.choices?.[0]?.message?.content || upstream.content?.[0]?.text || '';
} catch(e) { aiText = ''; }

let intent = {};
try {
  const cleaned = aiText.replace(/```json/gi,'').replace(/```/g,'').trim();
  intent = JSON.parse(cleaned);
  if (!intent.intent) throw new Error('Missing intent field');
} catch(e) {
  intent = {
    intent: 'manual_review',
    confidence: 0,
    reasoning: `Parse failed: ${e.message}`,
    appointmentType: '',
    firstName: '',
    isChild: false,
    preferredDate: ''
  };
}

// Confidence gate
if (intent.confidence < 0.75 && intent.intent !== 'manual_review') {
  intent.originalIntent = intent.intent;
  intent.intent = 'manual_review';
  intent.reasoning = `Low confidence (${intent.confidence}). Was: ${intent.originalIntent}`;
}

const bestFirstName = (intent.firstName && intent.firstName.trim()) ? intent.firstName : upstream.firstName || 'there';

return {
  json: {
    ...upstream,
    firstName: bestFirstName,
    intent: intent.intent,
    intentData: intent,
    appointmentType: intent.appointmentType || 'ADHD Assessment',
    isChild: intent.isChild || false,
    preferredDate: intent.preferredDate || ''
  }
};

// ============================================================
// NODE: Find Next Available Slots from Google Calendar
// PURPOSE: Query the consultant's Google Calendar for
//          'Available' events in the next 14 days and
//          return up to 3 options to propose to the patient.
// ============================================================
// NOTE: This node prepares the search parameters.
//       The actual Google Calendar query happens in the
//       next node (Google Calendar - Get Events).
// ============================================================

const d = $input.item.json;

// Search window: today → 14 days from now
const now = new Date();
const twoWeeksLater = new Date();
twoWeeksLater.setDate(twoWeeksLater.getDate() + 14);

// If patient mentioned a preferred date, try to honor it
// by searching from that date if it's in the future
let searchFrom = now;
if (d.preferredDate) {
  const preferred = new Date(d.preferredDate);
  if (!isNaN(preferred) && preferred > now) {
    searchFrom = preferred;
  }
}

return {
  json: {
    ...d,
    calendarSearchFrom: searchFrom.toISOString(),
    calendarSearchTo:   twoWeeksLater.toISOString(),
    searchWindowDays:   14
  }
};

// ============================================================
// NODE: Select Best 3 Slots & Build Proposal Email
// PURPOSE: From the available slots returned by Google
//          Calendar, pick the best 3 and build a friendly
//          email proposing them to the patient.
// ============================================================

const allItems = $input.all();
const bookingData = allItems[0]?.json || {};

// Collect all available events from the batch
const slots = allItems
  .filter(item => item.json.start?.dateTime) // timed events only, not all-day
  .map(item => ({
    id:        item.json.id,
    title:     item.json.summary || 'Available',
    start:     item.json.start.dateTime,
    end:       item.json.end?.dateTime || '',
    timezone:  item.json.start.timeZone || 'Europe/London'
  }))
  .slice(0, 3); // Take the first 3 available slots

if (slots.length === 0) {
  // No slots found — flag for manual handling
  return {
    json: {
      ...bookingData,
      noSlotsFound: true,
      availableSlots: []
    }
  };
}

// Format each slot for the email
const formatSlot = (slot, index) => {
  const date = new Date(slot.start);
  const endDate = new Date(slot.end);
  const dateStr = date.toLocaleDateString('en-GB', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    timeZone: 'Europe/London'
  });
  const startTime = date.toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Europe/London'
  });
  const endTime = endDate.toLocaleTimeString('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Europe/London'
  });
  return `Option ${index + 1}: ${dateStr} at ${startTime}–${endTime}`;
};

const slotLines = slots.map((s, i) => formatSlot(s, i)).join('\n');

// Build the proposal email body
const firstName = bookingData.firstName || 'there';
const appointmentType = bookingData.appointmentType || 'appointment';

const emailBody = `Dear ${firstName},

Thank you for getting in touch — we'd be happy to arrange a ${appointmentType} for you.

We have the following appointments available:

${slotLines}

Please simply reply to this email with which option works best for you, or let us know if none of these suit and we'll find an alternative.

Kind regards,
Admin Team
REPLACE_WITH_CLINIC_NAME
REPLACE_WITH_PHONE_NUMBER | REPLACE_WITH_WEBSITE`;

return {
  json: {
    ...bookingData,
    noSlotsFound:   false,
    availableSlots: slots,
    slotCount:      slots.length,
    emailSubject:   `Re: ${bookingData.subject}`,
    emailBody,
    // Store slot IDs so we can book the chosen one when patient confirms
    slot1Id:        slots[0]?.id || '',
    slot2Id:        slots[1]?.id || '',
    slot3Id:        slots[2]?.id || '',
    slot1Start:     slots[0]?.start || '',
    slot2Start:     slots[1]?.start || '',
    slot3Start:     slots[2]?.start || '',
    slot1End:       slots[0]?.end || '',
    slot2End:       slots[1]?.end || '',
    slot3End:       slots[2]?.end || ''
  }
};

// ============================================================
// NODE: Detect Which Slot Patient Confirmed
// PURPOSE: When the patient replies confirming an option,
//          parse their reply to determine which slot they
//          chose (Option 1, 2, or 3).
// ============================================================

const d = $input.item.json;
const bodyLower = (d.body || '').toLowerCase();

// --- Detect which option they chose ---
let chosenOption = 0;

// Check explicit option mentions
if (bodyLower.includes('option 1') || bodyLower.includes('first option') || bodyLower.includes('1st option')) {
  chosenOption = 1;
} else if (bodyLower.includes('option 2') || bodyLower.includes('second option') || bodyLower.includes('2nd option')) {
  chosenOption = 2;
} else if (bodyLower.includes('option 3') || bodyLower.includes('third option') || bodyLower.includes('3rd option')) {
  chosenOption = 3;
}

// If no explicit option mentioned, check for day/time mentions
// (Patient might say 'Monday works' or 'the 10am slot')
// In this case default to option 1 (earliest) with a flag for admin awareness
if (chosenOption === 0) {
  // Try to match any confirmation language
  const confirmWords = ['yes','confirm','that works','sounds good','perfect','great','happy with','prefer','i\'ll take','book me in','go ahead'];
  const isConfirming = confirmWords.some(w => bodyLower.includes(w));

  if (isConfirming) {
    chosenOption = 1; // Default to first option
  }
}

const needsManualReview = chosenOption === 0;

return {
  json: {
    ...d,
    chosenOption,
    needsManualReview,
    // These will be filled by a Sheets lookup in production
    // For now we use session data passed through the thread
    confirmedSlotNote: needsManualReview
      ? 'Could not determine which slot patient chose — admin should confirm'
      : `Patient confirmed Option ${chosenOption}`
  }
};

// ============================================================
// NODE: Look Up Original Booking from Sheets
// PURPOSE: Retrieve the slot times that were proposed to
//          this patient so we know which calendar event to
//          create for their chosen option.
// ============================================================
// In a full production setup, this would do a Google Sheets
// lookup by threadId to get the exact slot start/end times.
// For now, we prepare the lookup parameters.
// ============================================================

const d = $input.item.json;
const chosenOption = d.chosenOption || 1;

// Map chosen option to slot field names
const slotKey = `slot${chosenOption}Start`;
const slotEndKey = `slot${chosenOption}End`;

// These fields exist if the data was passed through correctly
// In a real deployment, do a Google Sheets lookup by threadId here
const slotStart = d[slotKey] || d.slot1Start || '';
const slotEnd   = d[slotEndKey] || d.slot1End || '';

return {
  json: {
    ...d,
    confirmedSlotStart: slotStart,
    confirmedSlotEnd:   slotEnd,
    calendarEventTitle: `${d.appointmentType} — ${d.senderName}`,
    calendarEventDesc:  `Patient: ${d.senderName}\nEmail: ${d.senderEmail}\nType: ${d.appointmentType}\nBooked via: Email\nConfirmed: ${new Date().toISOString()}`,
    calendarEventLocation: 'REPLACE_WITH_CLINIC_ADDRESS_OR_ZOOM'
  }
};
